import React, { useEffect, useState, useRef } from 'react';
import io from 'socket.io-client';

const Chat = () => {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [user, setUser] = useState(null);
  const socket = useRef();

  const token = localStorage.getItem('token');

    useEffect(() => {
  const newSocket = io('http://localhost:4000');
  socket.current = newSocket;

  newSocket.on("connect", () => {
    console.log("✅ Connected to server!");
  });

  newSocket.on("disconnect", () => {
    console.log("❌ Disconnected from server");
  });

  newSocket.on("receiveMessage", (message) => {
    console.log("📨 Message received:", message);
    setMessages(prev => [...prev, message]);
  });

  return () => {
    newSocket.disconnect();
  };
}, []);


  useEffect(() => {
    if (!token) return;

    // Connect to backend
    socket.current = io('http://localhost:4000', {
      auth: {
        token
      }
    });

    // Fetch user info
    fetch('http://localhost:4000/api/auth/me', {
      headers: { 'x-auth-token': token }
    }).then(res => res.json()).then(userData => {
      setUser(userData);
    });

    // Listen for messages
    socket.current.on('authenticated', () => {
      socket.current.on('receiveMessage', (msg) => {
        setMessages(prev => [...prev, msg]);
      });

      socket.current.on('userList', (users) => {
        console.log('Current users online:', users);
      });
    });

    socket.current.on('unauthorized', () => {
      alert('Authentication failed!');
      window.location.href = '/login';
    });

    return () => {
      socket.current.disconnect();
    };
  }, [token]);

  const sendMessage = (e) => {
    e.preventDefault();
    if (!message.trim()) return;

    const fullMessage = {
      text: message,
      username: user.username,
      time: new Date().toLocaleTimeString()
    };

    socket.current.emit('sendMessage', fullMessage);
    setMessage('');
  };

  return (
    <div>
      <h2>Real-Time Chat</h2>
      <div style={{ height: '300px', border: '1px solid #ccc', overflowY: 'auto', padding: '10px' }}>
        {messages.map((msg, i) => (
          <div key={i}>
            <strong>{msg.username}</strong> <small>{msg.time}</small><br />
            <span>{msg.text}</span><hr />
          </div>
        ))}
      </div>
      <form onSubmit={sendMessage}>
        <input
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Type a message..."
          style={{ width: '80%' }}
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
};

export default Chat;
